/**
 * Minimal, deterministic OpenType/TrueType metrics reader for the text engine (P06-44).
 *
 * Measurement must not depend on the browser (preview = final, MOTOR §3), so the engine reads the *pinned font file*
 * itself: `head`, `hhea`, `OS/2`, `maxp`, `hmtx`, `cmap` (formats 4 and 12), the `locl` single substitutions of GSUB
 * (Turkish `i` -> `i.loclTRK` etc.) and the pair-adjustment lookups of the GPOS `kern` feature (formats 1 and 2,
 * including extension lookups). That is exactly what Chromium's shaper applies to Latin/Cyrillic/Greek text once the
 * renderer disables ligatures (`font-variant-ligatures: none`, see the DOM binder), so widths computed here match the
 * rendered line boxes. Anything else (ligatures, contextual alternates, complex scripts) is outside this reader and is
 * refused upstream (`unsupported_script`) instead of being approximated.
 *
 * WOFF/WOFF2 and collections are refused: the font catalogue pins plain sfnt files (sha256) for both measurement and
 * rendering.
 */
import { MotionError } from '../errors'

/** OpenType script tags the engine measures (Q59 stage 1). */
export type OtScript = 'latn' | 'cyrl' | 'grek' | 'DFLT'

export interface PairAdjustment {
  /** XAdvance added to the first glyph (font units). */
  first: number
  /** XAdvance added to the second glyph (font units). */
  second: number
}

export interface ParsedFont {
  readonly units_per_em: number
  /** Line metrics in font units: OS/2 typo metrics when USE_TYPO_METRICS is set, otherwise `hhea`. */
  readonly ascender: number
  readonly descender: number
  readonly line_gap: number
  readonly num_glyphs: number
  /** Nominal glyph for a code point; 0 (`.notdef`) when the font has none. */
  glyph(codepoint: number): number
  /** Advance width in font units. */
  advance(glyph: number): number
  /** GSUB `locl` single substitution for the script / OpenType language system (e.g. `TRK`). */
  localize(glyph: number, script: OtScript, language: string | null): number
  /** GPOS `kern` pair adjustment for two adjacent base glyphs. */
  kerning(first: number, second: number, script: OtScript, language: string | null): PairAdjustment
}

function refuse(reason: string): never {
  throw new MotionError('font_refused', reason, [{ code: 'font_invalid', path: '', message: reason }])
}

class Reader {
  readonly view: DataView
  constructor(readonly bytes: Uint8Array) {
    this.view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  }
  check(offset: number, length: number): void {
    if (offset < 0 || offset + length > this.bytes.byteLength) refuse(`font table read out of bounds at ${offset}`)
  }
  u16(offset: number): number {
    this.check(offset, 2)
    return this.view.getUint16(offset)
  }
  i16(offset: number): number {
    this.check(offset, 2)
    return this.view.getInt16(offset)
  }
  u32(offset: number): number {
    this.check(offset, 4)
    return this.view.getUint32(offset)
  }
  tag(offset: number): string {
    this.check(offset, 4)
    return String.fromCharCode(this.bytes[offset] as number, this.bytes[offset + 1] as number, this.bytes[offset + 2] as number, this.bytes[offset + 3] as number)
  }
}

interface TableRecord {
  offset: number
  length: number
}

/** Coverage index of a glyph, or -1. */
function coverageIndex(r: Reader, offset: number, glyph: number): number {
  const format = r.u16(offset)
  if (format === 1) {
    let lo = 0
    let hi = r.u16(offset + 2) - 1
    while (lo <= hi) {
      const mid = (lo + hi) >> 1
      const value = r.u16(offset + 4 + mid * 2)
      if (value === glyph) return mid
      if (value < glyph) lo = mid + 1
      else hi = mid - 1
    }
    return -1
  }
  if (format === 2) {
    let lo = 0
    let hi = r.u16(offset + 2) - 1
    while (lo <= hi) {
      const mid = (lo + hi) >> 1
      const record = offset + 4 + mid * 6
      const start = r.u16(record)
      const end = r.u16(record + 2)
      if (glyph < start) hi = mid - 1
      else if (glyph > end) lo = mid + 1
      else return r.u16(record + 4) + glyph - start
    }
    return -1
  }
  return refuse(`unknown coverage format ${format}`)
}

function classOf(r: Reader, offset: number, glyph: number): number {
  const format = r.u16(offset)
  if (format === 1) {
    const start = r.u16(offset + 2)
    const count = r.u16(offset + 4)
    return glyph >= start && glyph < start + count ? r.u16(offset + 6 + (glyph - start) * 2) : 0
  }
  if (format === 2) {
    let lo = 0
    let hi = r.u16(offset + 2) - 1
    while (lo <= hi) {
      const mid = (lo + hi) >> 1
      const record = offset + 4 + mid * 6
      const start = r.u16(record)
      const end = r.u16(record + 2)
      if (glyph < start) hi = mid - 1
      else if (glyph > end) lo = mid + 1
      else return r.u16(record + 4)
    }
    return 0
  }
  return refuse(`unknown class definition format ${format}`)
}

function valueRecordSize(format: number): number {
  let bits = 0
  for (let bit = format & 0xff; bit; bit >>= 1) bits += bit & 1
  return bits * 2
}

/** Offset of XAdvance inside a value record, or -1 when the format carries none. */
function xAdvanceOffset(format: number): number {
  if (!(format & 0x4)) return -1
  return ((format & 0x1) ? 2 : 0) + ((format & 0x2) ? 2 : 0)
}

/** Layout table (GSUB/GPOS) access: feature -> lookup selection and extension unwrapping. */
class LayoutTable {
  private readonly lookupCache = new Map<string, number[]>()
  constructor(
    private readonly r: Reader,
    private readonly base: number,
    private readonly extensionType: number,
  ) {}

  /** Lookup indices of `feature` for the script / language system, in lookup-list order. */
  lookups(feature: string, script: OtScript, language: string | null): number[] {
    const key = `${feature}|${script}|${language ?? ''}`
    const cached = this.lookupCache.get(key)
    if (cached) return cached
    const { r, base } = this
    const scriptList = base + r.u16(base + 4)
    const featureList = base + r.u16(base + 6)
    const scriptCount = r.u16(scriptList)
    const findScript = (tag: string): number | null => {
      for (let i = 0; i < scriptCount; i++) {
        const record = scriptList + 2 + i * 6
        if (r.tag(record) === tag) return scriptList + r.u16(record + 4)
      }
      return null
    }
    const scriptTable = findScript(script) ?? findScript('DFLT') ?? findScript('latn')
    const result: number[] = []
    if (scriptTable !== null) {
      let langSys = 0
      if (language) {
        const count = r.u16(scriptTable + 2)
        for (let i = 0; i < count; i++) {
          const record = scriptTable + 4 + i * 6
          if (r.tag(record).trimEnd() === language) langSys = scriptTable + r.u16(record + 4)
        }
      }
      if (!langSys && r.u16(scriptTable)) langSys = scriptTable + r.u16(scriptTable)
      if (langSys) {
        const indices: number[] = []
        const required = r.u16(langSys + 2)
        if (required !== 0xffff) indices.push(required)
        const count = r.u16(langSys + 4)
        for (let i = 0; i < count; i++) indices.push(r.u16(langSys + 6 + i * 2))
        const seen = new Set<number>()
        for (const index of indices) {
          const record = featureList + 2 + index * 6
          if (r.tag(record) !== feature) continue
          const table = featureList + r.u16(record + 4)
          const lookupCount = r.u16(table + 2)
          for (let j = 0; j < lookupCount; j++) seen.add(r.u16(table + 4 + j * 2))
        }
        result.push(...[...seen].sort((a, b) => a - b))
      }
    }
    this.lookupCache.set(key, result)
    return result
  }

  /** Subtables of a lookup as `[type, absolute offset]`, with extension subtables unwrapped. */
  subtables(lookupIndex: number): [number, number][] {
    const { r, base } = this
    const lookupList = base + r.u16(base + 8)
    const lookup = lookupList + r.u16(lookupList + 2 + lookupIndex * 2)
    const type = r.u16(lookup)
    const count = r.u16(lookup + 4)
    const out: [number, number][] = []
    for (let i = 0; i < count; i++) {
      const subtable = lookup + r.u16(lookup + 6 + i * 2)
      if (type === this.extensionType) out.push([r.u16(subtable + 2), subtable + r.u32(subtable + 4)])
      else out.push([type, subtable])
    }
    return out
  }
}

export function parseFont(bytes: Uint8Array): ParsedFont {
  const r = new Reader(bytes)
  if (bytes.byteLength < 12) refuse('font file too short')
  const signature = r.tag(0)
  if (signature === 'wOFF' || signature === 'wOF2') refuse('WOFF/WOFF2 fonts are not pinned sfnt files; use the catalogue TTF/OTF')
  if (signature === 'ttcf') refuse('font collections are not supported; pin a single face')
  if (!(r.u32(0) === 0x00010000 || signature === 'OTTO' || signature === 'true')) refuse('not an OpenType/TrueType file')

  const tables = new Map<string, TableRecord>()
  const numTables = r.u16(4)
  for (let i = 0; i < numTables; i++) {
    const record = 12 + i * 16
    const table = { offset: r.u32(record + 8), length: r.u32(record + 12) }
    r.check(table.offset, table.length)
    tables.set(r.tag(record), table)
  }
  const need = (tag: string): number => {
    const table = tables.get(tag)
    if (!table) refuse(`font has no ${tag} table`)
    return table.offset
  }

  const head = need('head')
  const unitsPerEm = r.u16(head + 18)
  if (unitsPerEm < 16 || unitsPerEm > 16384) refuse(`invalid unitsPerEm ${unitsPerEm}`)
  const hhea = need('hhea')
  const numGlyphs = r.u16(need('maxp') + 4)
  const numberOfHMetrics = r.u16(hhea + 34)
  if (numberOfHMetrics < 1 || numberOfHMetrics > numGlyphs) refuse('invalid numberOfHMetrics')
  const hmtx = need('hmtx')
  r.check(hmtx, numberOfHMetrics * 4)

  let ascender = r.i16(hhea + 4)
  let descender = r.i16(hhea + 6)
  let lineGap = r.i16(hhea + 8)
  const os2 = tables.get('OS/2')
  if (os2 && os2.length >= 78 && r.u16(os2.offset + 62) & (1 << 7)) {
    ascender = r.i16(os2.offset + 68)
    descender = r.i16(os2.offset + 70)
    lineGap = r.i16(os2.offset + 72)
  }

  // cmap: prefer a full-repertoire format 12 subtable, else a BMP format 4 one (Unicode or Windows Unicode BMP).
  const cmap = need('cmap')
  const cmapCount = r.u16(cmap + 2)
  let format12 = -1
  let format4 = -1
  for (let i = 0; i < cmapCount; i++) {
    const record = cmap + 4 + i * 8
    const platform = r.u16(record)
    const encoding = r.u16(record + 2)
    const subtable = cmap + r.u32(record + 4)
    const format = r.u16(subtable)
    const unicode = platform === 0 || (platform === 3 && (encoding === 1 || encoding === 10))
    if (!unicode) continue
    if (format === 12 && format12 < 0) format12 = subtable
    if (format === 4 && format4 < 0) format4 = subtable
  }
  if (format12 < 0 && format4 < 0) refuse('font has no Unicode cmap (format 4 or 12)')

  const glyphCache = new Map<number, number>()
  const lookupGlyph = (cp: number): number => {
    if (format12 >= 0) {
      let lo = 0
      let hi = r.u32(format12 + 12) - 1
      while (lo <= hi) {
        const mid = (lo + hi) >> 1
        const group = format12 + 16 + mid * 12
        const start = r.u32(group)
        const end = r.u32(group + 4)
        if (cp < start) hi = mid - 1
        else if (cp > end) lo = mid + 1
        else return r.u32(group + 8) + cp - start
      }
      return 0
    }
    if (cp > 0xffff) return 0
    const segCountX2 = r.u16(format4 + 6)
    const segCount = segCountX2 / 2
    const ends = format4 + 14
    const starts = ends + segCountX2 + 2
    const deltas = starts + segCountX2
    const ranges = deltas + segCountX2
    let lo = 0
    let hi = segCount - 1
    while (lo <= hi) {
      const mid = (lo + hi) >> 1
      const end = r.u16(ends + mid * 2)
      const start = r.u16(starts + mid * 2)
      if (cp > end) lo = mid + 1
      else if (cp < start) hi = mid - 1
      else {
        const delta = r.u16(deltas + mid * 2)
        const rangeOffset = r.u16(ranges + mid * 2)
        if (rangeOffset === 0) return (cp + delta) & 0xffff
        const glyph = r.u16(ranges + mid * 2 + rangeOffset + (cp - start) * 2)
        return glyph === 0 ? 0 : (glyph + delta) & 0xffff
      }
    }
    return 0
  }

  const gsubRecord = tables.get('GSUB')
  const gposRecord = tables.get('GPOS')
  const gsub = gsubRecord ? new LayoutTable(r, gsubRecord.offset, 7) : null
  const gpos = gposRecord ? new LayoutTable(r, gposRecord.offset, 9) : null
  const kernCache = new Map<string, PairAdjustment>()

  const pairFormat1 = (subtable: number, first: number, second: number, index: number): PairAdjustment | null => {
    const vf1 = r.u16(subtable + 4)
    const vf2 = r.u16(subtable + 6)
    const pairSet = subtable + r.u16(subtable + 10 + index * 2)
    const size1 = valueRecordSize(vf1)
    const recordSize = 2 + size1 + valueRecordSize(vf2)
    let lo = 0
    let hi = r.u16(pairSet) - 1
    while (lo <= hi) {
      const mid = (lo + hi) >> 1
      const record = pairSet + 2 + mid * recordSize
      const glyph = r.u16(record)
      if (glyph < second) lo = mid + 1
      else if (glyph > second) hi = mid - 1
      else {
        const x1 = xAdvanceOffset(vf1)
        const x2 = xAdvanceOffset(vf2)
        return { first: x1 >= 0 ? r.i16(record + 2 + x1) : 0, second: x2 >= 0 ? r.i16(record + 2 + size1 + x2) : 0 }
      }
    }
    return null
  }

  const pairFormat2 = (subtable: number, first: number, second: number): PairAdjustment | null => {
    const vf1 = r.u16(subtable + 4)
    const vf2 = r.u16(subtable + 6)
    const class1 = classOf(r, subtable + r.u16(subtable + 8), first)
    const class2 = classOf(r, subtable + r.u16(subtable + 10), second)
    const class1Count = r.u16(subtable + 12)
    const class2Count = r.u16(subtable + 14)
    if (class1 >= class1Count || class2 >= class2Count) return null
    const size1 = valueRecordSize(vf1)
    const recordSize = size1 + valueRecordSize(vf2)
    const record = subtable + 16 + (class1 * class2Count + class2) * recordSize
    const x1 = xAdvanceOffset(vf1)
    const x2 = xAdvanceOffset(vf2)
    return { first: x1 >= 0 ? r.i16(record + x1) : 0, second: x2 >= 0 ? r.i16(record + size1 + x2) : 0 }
  }

  return {
    units_per_em: unitsPerEm,
    ascender,
    descender,
    line_gap: lineGap,
    num_glyphs: numGlyphs,
    glyph(codepoint) {
      let glyph = glyphCache.get(codepoint)
      if (glyph === undefined) {
        glyph = lookupGlyph(codepoint)
        if (glyph >= numGlyphs) glyph = 0
        glyphCache.set(codepoint, glyph)
      }
      return glyph
    },
    advance(glyph) {
      const index = Math.min(glyph, numberOfHMetrics - 1)
      return r.u16(hmtx + index * 4)
    },
    localize(glyph, script, language) {
      if (!gsub || !language) return glyph
      let current = glyph
      for (const lookup of gsub.lookups('locl', script, language)) {
        for (const [type, subtable] of gsub.subtables(lookup)) {
          if (type !== 1) continue
          const index = coverageIndex(r, subtable + r.u16(subtable + 2), current)
          if (index < 0) continue
          const format = r.u16(subtable)
          if (format === 1) current = (current + r.i16(subtable + 4)) & 0xffff
          else if (format === 2) current = r.u16(subtable + 6 + index * 2)
          break
        }
      }
      return current
    },
    kerning(first, second, script, language) {
      const key = `${script}|${language ?? ''}|${first}|${second}`
      const cached = kernCache.get(key)
      if (cached) return cached
      const total: PairAdjustment = { first: 0, second: 0 }
      if (gpos) {
        for (const lookup of gpos.lookups('kern', script, language)) {
          for (const [type, subtable] of gpos.subtables(lookup)) {
            if (type !== 2) continue
            const index = coverageIndex(r, subtable + r.u16(subtable + 2), first)
            if (index < 0) continue
            const format = r.u16(subtable)
            const value = format === 1 ? pairFormat1(subtable, first, second, index) : format === 2 ? pairFormat2(subtable, first, second) : null
            if (!value) continue
            total.first += value.first
            total.second += value.second
            break
          }
        }
      }
      kernCache.set(key, total)
      return total
    },
  }
}
